import heapq

def cheapest_pairs(a, b, k):
    if not a or not b:
        return []
    heap = [(a[i] + b[0], i, 0) for i in range(min(k, len(a)))]
    heapq.heapify(heap)
    costs = []
    while heap and len(costs) < k:
        cost, i, j = heapq.heappop(heap)
        costs.append(cost)
        if j + 1 < len(b):
            heapq.heappush(heap, (a[i] + b[j + 1], i, j + 1))
    return costs

